class Solution:
    def mostServed(self, customers: List[int], moody: List[int], minutes: int) -> int:
        n, best = len(customers), 0
        for i in range(n - minutes + 1):
            happy = sum(customers[j] for j in range(n) if not moody[j] or i <= j < i + minutes)
            best = max(best, happy)
        return best

