class Solution {
    public int mostServed(int[] customers, int[] moody, int minutes) {
        int n = customers.length, best = 0;
        for (int i = 0; i + minutes <= n; i++) {
            int happy = 0;
            for (int j = 0; j < n; j++) if (moody[j] == 0 || (j >= i && j < i + minutes)) happy += customers[j];
            best = Math.max(best, happy);
        }
        return best;
    }
}

