class Solution:
    def mostServed(self, customers: List[int], moody: List[int], minutes: int) -> int:
        base = sum(c for c, m in zip(customers, moody) if m == 0)
        gain = sum(customers[i] * moody[i] for i in range(minutes))
        best = gain
        for i in range(minutes, len(customers)):
            gain += customers[i] * moody[i] - customers[i - minutes] * moody[i - minutes]
            best = max(best, gain)
        return base + best

