        int n = customers.length, base = 0, gain = 0;
        for (int i = 0; i < n; i++) if (moody[i] == 0) base += customers[i];
        for (int i = 0; i < minutes; i++) gain += customers[i] * moody[i];
        int best = gain;
        for (int i = minutes; i < n; i++) {
            gain += customers[i] * moody[i] - customers[i - minutes] * moody[i - minutes];
            best = Math.max(best, gain);
        }
        return base + best;
    }
}

